66	const deviceSettingsUnavailable = (device?: TrezorDevice) => {
67	    const wrongDeviceType = device?.type && ['unacquired', 'unreadable'].includes(device.type);
68	    const wrongDeviceMode =
69	        (device?.mode && ['seedless'].includes(device.mode)) ||
70	        (device?.features !== undefined && isRecoveryInProgress(device?.features));
71	    const firmwareUpdateRequired = device?.firmware === 'required';
72	
73	    return wrongDeviceType || wrongDeviceMode || firmwareUpdateRequired;
74	};
