76	export const SettingsDevice = () => {
77	    const dispatch = useDispatch();
78	    const hasContentBelowTabletWidth = useIsContentBelowBreakpoint(breakpoints.tablet);
79	    const hasContentBelowLaptopWidth = useIsContentBelowBreakpoint(breakpoints.laptop);
80	    const { device, isLocked } = useDevice();
81	    const noTransportAvailable = !useSelector(selectHasActiveTransport);
82	    const deviceUnavailable = !device?.features;
83	    const isDeviceLocked = isLocked();
84	    const bootloaderMode = device?.mode === 'bootloader';
85	    const initializeMode = device?.mode === 'initialize';
86	    const isNormalMode = !bootloaderMode && !initializeMode;
87	    const deviceRemembered = getIsDeviceRemembered(device) && !device?.connected;
88	    const bitcoinOnlyDevice = isBitcoinOnlyDevice(device);
89	    const shouldShowNoDeviceEshopBanner = useSelector(selectShouldShowNoDeviceEshopSettingsBanner);
90	    const supportsDeviceAuthentication = useSelector(selectIsDeviceAuthenticityCheckSupported);
91	
92	    if (noTransportAvailable || deviceSettingsUnavailable(device)) {
93	        return (
94	            <SettingsLayout>
95	                <DeviceBanner
96	                    title={<Translation id="TR_SETTINGS_DEVICE_BANNER_TITLE_UNAVAILABLE" />}
97	                    description={
98	                        <Translation id="TR_SETTINGS_DEVICE_BANNER_DESCRIPTION_UNAVAILABLE" />
99	                    }
100	                />
101	            </SettingsLayout>
102	        );
103	    }
104	
105	    if (deviceUnavailable) {
106	        return (
107	            <SettingsLayout>
108	                <DeviceBanner
109	                    intent="info"
110	                    title={<Translation id="TR_SETTINGS_DEVICE_BANNER_TITLE_DISCONNECTED" />}
111	                    description={
112	                        <Translation id="TR_SETTINGS_DEVICE_BANNER_DESCRIPTION_DISCONNECTED" />
113	                    }
114	                    rightContent={
115	                        <Banner.Button onClick={() => dispatch(setConnectionModal(true))}>
116	                            <Translation id="TR_CONNECT" />
117	                        </Banner.Button>
118	                    }
119	                />
120	                {shouldShowNoDeviceEshopBanner && (
121	                    <SettingsSection
122	                        title={<Translation id="TR_TREZOR_WALLET" />}
123	                        hasContainer={false}
124	                        icon={TrezorLogoIcon}
125	                        hasVerticalLayout={hasContentBelowLaptopWidth}
126	                    >
127	                        <NoDeviceEshopSettingsBanner />
128	                    </SettingsSection>
129	                )}
130	            </SettingsLayout>
131	        );
132	    }
133	
134	    const {
135	        unfinished_backup: unfinishedBackup,
136	        pin_protection: pinProtection,
137	        safety_checks: safetyChecks,
138	    } = device.features;
139	
140	    const deviceModelInternal = device.features.internal_model;
141	
142	    // because Device authenticity check is something you can (and have to) do on a device with FW but without seed
143	    const isSecuritySectionVisible =
144	        isNormalMode || (initializeMode && supportsDeviceAuthentication);
145	
146	    const isThpDevice = device?.thp !== undefined;
147	
148	    const bootloaderDescription = getHowToGetFromBootloaderInstructionsMap({ deviceModelInternal });
149	
150	    return (
151	        <SettingsLayout>
152	            <ContextMessage context={Context.getSettings('device')} />
153	
154	            {bootloaderMode && (
155	                <DeviceBanner
156	                    title={<Translation id="TR_SETTINGS_DEVICE_BANNER_TITLE_BOOTLOADER" />}
157	                    description={
158	                        bootloaderDescription !== null ? (
159	                            <Translation id={bootloaderDescription} />
160	                        ) : null
161	                    }
162	                />
163	            )}
164	
165	            {deviceRemembered && (
166	                <DeviceBanner
167	                    title={<Translation id="TR_SETTINGS_DEVICE_BANNER_TITLE_REMEMBERED" />}
168	                />
169	            )}
170	
171	            {isNormalMode && (
172	                <SettingsSection
173	                    hasVerticalLayout={hasContentBelowTabletWidth}
174	                    title={<Translation id="TR_BACKUP" />}
175	                    icon={NewspaperIcon}
176	                >
177	                    {unfinishedBackup ? (
178	                        <BackupFailed />
179	                    ) : (
180	                        <>
181	                            <BackupRecoverySeed isDeviceLocked={isDeviceLocked} />
182	                            <MultiShareBackup isDeviceLocked={isDeviceLocked} />
183	                            <CheckRecoverySeed isDeviceLocked={isDeviceLocked} />
184	                            <CreateWalletBackup isDeviceLocked={isDeviceLocked} />
185	                        </>
186	                    )}
187	                </SettingsSection>
188	            )}
189	
190	            <SettingsSection
191	                hasVerticalLayout={hasContentBelowTabletWidth}
192	                title={<Translation id="TR_PASSPHRASE" />}
193	                icon={PasswordIcon}
194	            >
195	                <Passphrase isDeviceLocked={isDeviceLocked} />
196	            </SettingsSection>
197	
198	            <SettingsSection
199	                hasVerticalLayout={hasContentBelowTabletWidth}
200	                title={<Translation id="TR_FIRMWARE" />}
201	                icon={PuzzlePieceIcon}
202	            >
203	                <FirmwareVersion isDeviceLocked={isDeviceLocked} />
204	                {(!bootloaderMode || bitcoinOnlyDevice) && (
205	                    <FirmwareTypeChange isDeviceLocked={isDeviceLocked} />
206	                )}
207	                <ChangeLanguage isDeviceLocked={isDeviceLocked} />
208	            </SettingsSection>
209	
210	            {isSecuritySectionVisible && (
211	                <SettingsSection
212	                    hasVerticalLayout={hasContentBelowTabletWidth}
213	                    title={<Translation id="TR_DEVICE_SECURITY" />}
214	                    icon={ShieldCheckIcon}
215	                >
216	                    {isNormalMode && (
217	                        <>
218	                            <PinProtection isDeviceLocked={isDeviceLocked} />
219	                            {pinProtection && <ChangePin isDeviceLocked={isDeviceLocked} />}
220	                            {safetyChecks && <SafetyChecks isDeviceLocked={isDeviceLocked} />}
221	                        </>
222	                    )}
223	                    {supportsDeviceAuthentication && (
224	                        <AuthenticateDevice isDeviceLocked={isDeviceLocked} />
225	                    )}
226	                </SettingsSection>
227	            )}
228	
229	            {isNormalMode && (
230	                <SettingsSection
231	                    hasVerticalLayout={hasContentBelowTabletWidth}
232	                    title={<Translation id="TR_PERSONALIZATION" />}
233	                    icon={PaletteIcon}
234	                >
235	                    <DeviceLabel isDeviceLocked={isDeviceLocked} />
236	                    <Homescreen isDeviceLocked={isDeviceLocked} />
237	                    <DisplayRotation isDeviceLocked={isDeviceLocked} />
238	                    <Brightness isDeviceLocked={isDeviceLocked} />
239	                    <HapticFeedback isDeviceLocked={isDeviceLocked} />
240	                    {pinProtection && <AutoLock isDeviceLocked={isDeviceLocked} />}
241	                </SettingsSection>
242	            )}
243	
244	            <SettingsSection
245	                hasVerticalLayout={hasContentBelowTabletWidth}
246	                title={<Translation id="TR_DEVICE_CONNECTION" />}
247	                icon={PlugsIcon}
248	            >
249	                {isThpDevice && <ThpAutoconnect isDeviceLocked={isDeviceLocked} />}
250	                <ForgetDevice />
251	            </SettingsSection>
252	
253	            <SettingsSection
254	                hasVerticalLayout={hasContentBelowTabletWidth}
255	                title={<Translation id="TR_SETTINGS_ADVANCED" />}
256	                icon={ShieldWarningIcon}
257	            >
258	                <DeviceAuthenticityOptOut
259	                    isDeviceAuthenticityCheckSupported={supportsDeviceAuthentication}
260	                />
261	                <FirmwareAuthenticityChecks />
262	            </SettingsSection>
263	
264	            <SettingsSection
265	                hasVerticalLayout={hasContentBelowTabletWidth}
266	                title={<Translation id="TR_ADVANCED" />}
267	                icon={GhostIcon}
268	            >
269	                <WipeDevice isDeviceLocked={isDeviceLocked} />
270	                {isNormalMode && <WipeCode isDeviceLocked={isDeviceLocked} />}
271	                <CustomFirmware />
272	            </SettingsSection>
273	        </SettingsLayout>
274	    );
275	};
